        @test reshape(b,10,1) .* A == A .* reshape(b,10,1) == A .* b
        @test bandwidths(reshape(b,10,1) .* A) == bandwidths(A)
        @test bandwidths(A .* reshape(b,10,1)) == bandwidths(A)

        @test b .+ A == b .+ Matrix(A) == A .+ b

        @test bandwidths(broadcasted(+, A, b')) == (9,9)
