        @test bandwidths(A .+ b') == bandwidths(b' .+ A)  == (9,9)
        @test A .* b' == b' .* A == Matrix(A) .* b'
        @test bandwidths(A .* b') == bandwidths(b' .* A) == bandwidths(A)

