func Netstat(c chan<- model.Metric) {
	stats, err := nux.Netstat()
	if err != nil {
		log.Println("Failed to get netstat:", err)
		return
	}

	for _, v := range stats {
		metric := model.Metric{
			Metric: "netstat_" + v.Name,
			Value:  v.Value,
			Tags:   "type=" + v.Type,
		}
		c <- metric
	}
}

