func createServerMux() *http.ServeMux {
	serveMux := http.NewServeMux()
	// handle "/" pattern
	serveMux.HandleFunc("/", handleRootPath)
	return serveMux
}

func handleRootPath(resp http.ResponseWriter, req *http.Request) {
	fmt.Fprintln(resp, "proto:", strconv.Quote(req.Proto))
	fmt.Fprintln(resp, "host:", strconv.Quote(req.Host))
	fmt.Fprintln(resp, "URI:", strconv.Quote(req.RequestURI))
