func (key Key) String() string {
	var buf bytes.Buffer
	buf.WriteString("[")
	for i, part := range key {
		if i > 0 {
			buf.WriteString(", ")
		}
		switch v := part.(type) {
		case string:
			buf.WriteString(fmt.Sprintf("%q", v))
		case []byte:
			buf.WriteString(fmt.Sprintf("%q", v))
		case NullString:
			if v.Valid {
				buf.WriteString(fmt.Sprintf("%q", v.String))
			} else {
				buf.WriteString("<nil>")
			}
		default:
			buf.WriteString(fmt.Sprintf("%v", v))
		}
	}
	buf.WriteString("]")
	return buf.String()
}

