// ServeHTTP implements the http.Handler interface.
func (rh *rootHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// The context is enriched with request-scoped information.
	ctx := ctxu.WithRequestID(rh.context, r)

	// Log the incoming request.
	ctx = ctxu.WithLogger(ctx, logrus.New()) // TODO: This should be a shared logger
	logrus.WithFields(logrus.Fields{
		"method": r.Method,
		"path":   r.URL.Path,
	}).Debug("incoming request")

	// Perform authorization.
	if err := rh.auth.Authorize(ctx, r, rh.actions...); err != nil {
		errcode.ServeJSONError(ctx, w, err)
		return
	}

	// Call the alternate handler.
	if err := rh.handler(ctx, w, r); err != nil {
		errcode.ServeJSONError(ctx, w, err)
		return
	}
}

