// QueryRow executes a query that is expected to return at most one row.
// Success is determined by whether the returned row is the zero value for
// the destination type.
func (c *Context) QueryRow(rows *sql.Rows, dst interface{}) error {
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return sql.ErrNoRows
	}
	if err := c.ScanRow(rows, dst); err != nil {
		return err
	}
	if rows.Next() {
		return fmt.Errorf("sqlutil: expected at most one row, got more")
	}
	return rows.Err()
}

