// Query queries the database for rows and scans the first row into dst.
// If no rows are returned, Query returns sql.ErrNoRows.
func (c *Context) Query(db DB, query string, args ...interface{}) (err error) {
	rows, err := db.Query(query, c.convertValues(args)...)
	if err != nil {
		return err
	}
	defer rows.Close()

	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return sql.ErrNoRows
	}

	if err := c.ScanRow(rows, nil, nil, dst); err != nil {
		return err
	}

	if err := rows.Next(); err == nil {
		return fmt.Errorf("sqlutil: expected one row, got more")
	}

	return rows.Err()
}

