		}

		user, err := s.GetUserByUsername(username)
		if err != nil {
			log.Error("Failed to retrieve user: ", err)
			return false
		}

		return bcrypt.CompareHashAndPassword([]byte(user.PasswordHash), []byte(password)) == nil
	})
}

