// BasicAuthMiddleware returns a basic authentication middleware.
func BasicAuthMiddleware(users map[string]string) echo.MiddlewareFunc {
	return middleware.BasicAuth(func(username, password string) (bool, error) {
		if storedPassword, ok := users[username]; ok {
			if err := bcrypt.CompareHashAndPassword([]byte(storedPassword), []byte(password)); err == nil {
				return true, nil
			}
		}
		return false, nil
	})
}

