				dlit.MustNew(44), dlit.MustNew(46), dlit.MustNew(48),
			},
		},
		{min: dlit.MustNew(10), max: dlit.MustNew(15), maxDP: 1,
			want: []*dlit.Literal{
				dlit.MustNew(10.3), dlit.MustNew(10.5),
				dlit.MustNew(10.8), dlit.MustNew(11), dlit.MustNew(11.3),
