				dlit.MustNew(13.8), dlit.MustNew(14), dlit.MustNew(14.3),
				dlit.MustNew(14.5), dlit.MustNew(14.8),
			},
		},
		{min: dlit.MustNew(10.2678945), max: dlit.MustNew(15.2382745),
