	if err != nil {
		lastErr = err
	}
	accessSecret, err := credential.GetAccessKeySecret()
	if err != nil {
		lastErr = err
	}
	stsToken, err := credential.GetSecurityToken()
	if err != nil {
		lastErr = err
	}
	if lastErr != nil {
		return "", "", "", lastErr
	}
	return *accessKeyID, *accessSecret, *stsToken, nil
}

