    assert_eq!('\u{a1}'.width(false),Some(1));
    assert_eq!('\u{a1}'.width(true),Some(2));

    assert_eq!('\u{300}'.width(false),Some(0));
    assert_eq!('\u{300}'.width(true),Some(0));
}

