#[test]
fn test_to_uppercase() {
    fn upper(c: char) -> char {
        let mut it = c.to_uppercase();
        let c = it.next().unwrap();
        // As of Unicode version 7.0.0, `SpecialCasing.txt` has no upper-case mapping
        // to multiple code points.
        assert!(it.next().is_none());
        c
    }
    assert_eq!(upper('a'), 'A');
    assert_eq!(upper('ö'), 'Ö');
    assert_eq!(upper('ß'), 'ß');
    assert_eq!(upper('ü'), 'Ü');
    assert_eq!(upper('💩'), '💩');
    assert_eq!(upper('σ'), 'Σ');
    assert_eq!(upper('τ'), 'Τ');
    assert_eq!(upper('i'), 'I');
}

